namespace ResearchAgent;

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
public sealed class NoteService
{
    private readonly List<Note> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add(new Note(title, content, DateTime.UtcNow));
    }

    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();

    public string GetSummary()
    {
        if (_notes.Count == 0)
            return "No notes recorded yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Title}\n{n.Content}"));
    }
}

public sealed record Note(string Title, string Content, DateTime CreatedAt);

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent: web search and note-taking.
/// </summary>
public sealed class ResearchTools(NoteService noteService)
{
    private static readonly HttpClient HttpClient = new();

    [Description("Search the web for information on a topic. Returns a list of relevant results with titles and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Uses DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await HttpClient.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main topic summary)
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var snippet = text.GetString();
                        if (!string.IsNullOrWhiteSpace(snippet))
                            results.Add(snippet);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing your search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string TakeNote(
        [Description("A short descriptive title for this note")] string title,
        [Description("The content/findings to record")] string content)
    {
        noteService.AddNote(title, content);
        var count = noteService.GetAllNotes().Count;
        return $"Note saved: '{title}' (total notes: {count})";
    }

    [Description("Retrieve all research notes taken so far. Use this to review findings before writing a summary.")]
    public string GetNotes()
    {
        return noteService.GetSummary();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

namespace ResearchAgent;

/// <summary>
/// Hosted service that runs the research agent workflow.
/// </summary>
public sealed class ResearchHostedService(
    IChatClient chatClient,
    ResearchTools tools,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════╗");
        Console.WriteLine("║       AI Research Agent              ║");
        Console.WriteLine("╚══════════════════════════════════════╝");
        Console.WriteLine();

        Console.Write("Enter a research topic: ");
        var topic = Console.ReadLine()?.Trim();

        if (string.IsNullOrWhiteSpace(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}");
        Console.WriteLine(new string('─', 50));

        try
        {
            await RunAgentAsync(topic, stoppingToken);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"\nError: {ex.Message}");
        }

        lifetime.StopApplication();
    }

    private async Task RunAgentAsync(string topic, CancellationToken ct)
    {
        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Instructions = """
                You are a thorough research agent. Your goal is to research the given topic 
                by searching the web for relevant information, taking notes on key findings, 
                and then producing a comprehensive summary.

                Follow this workflow:
                1. Search the web with multiple queries to gather diverse information about the topic.
                2. Take notes on the most important findings from each search.
                3. Review your notes to identify key themes and gaps.
                4. If there are gaps, do additional searches.
                5. Once you have enough information, retrieve all your notes and write a 
                   well-structured final summary.

                Be thorough but concise. Focus on factual information and cite sources when possible.
                """,
        };

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [
                AIFunctionFactory.Create(tools.SearchWeb),
                AIFunctionFactory.Create(tools.TakeNote),
                AIFunctionFactory.Create(tools.GetNotes),
            ],
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
        };

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 10,
            ChatOptions = chatOptions,
        };

        Console.WriteLine("\n[Agent working...]\n");

        await foreach (var message in agent.InvokeStreamingAsync(history, options, ct))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine("\n");
        Console.WriteLine(new string('═', 50));
        Console.WriteLine("Research complete.");
    }
}

